<?php
declare(strict_types=1);
require_once __DIR__.'/includes/portal.php';
$db=portalDb();$u=portalUser($db,'student');$rows=cbQuery($db,"SELECT e.id AS enrollment_id,s.*,COALESCE(m.status,'active') AS member_status,COALESCE(c.archived,0) AS archived FROM enrollments e JOIN subjects s ON s.id=e.subject_id LEFT JOIN classbook_members m ON m.enrollment_id=e.id LEFT JOIN classbook_settings c ON c.subject_id=s.id WHERE e.student_id=? ORDER BY s.school_year DESC,s.id ASC",[$u['id']])->fetchAll();
$recordsBySubject=[];$terms=[];$reqSubject=(int)($_GET['subject_id']??0);
foreach($rows as $s){
    $release=cbStudentRelease($db,(int)$s['id'],(int)$s['enrollment_id']);
    if(!$release&&($s['member_status']!=='active'||(int)$s['archived']===1))continue;
    $display=$release['snapshot']['class']??$s;$key=$display['school_year'].'|'.$display['semester'];$terms[$key]=$display['school_year'].' · '.$display['semester'];
    $dedupKey=$key.'|'.strtoupper(trim((string)$display['subject_code']));
    $candidate=['live'=>$s,'class'=>$display,'release'=>$release,'term'=>$key];
    if(!isset($recordsBySubject[$dedupKey])){$recordsBySubject[$dedupKey]=$candidate;}
    else{
        $existing=$recordsBySubject[$dedupKey];
        $hasRel=isset($release['snapshot']['students'][$s['enrollment_id']]);
        $exHasRel=isset($existing['release']['snapshot']['students'][$existing['live']['enrollment_id']]);
        if(((int)$s['id']===$reqSubject&&$hasRel)||($hasRel&&!$exHasRel))$recordsBySubject[$dedupKey]=$candidate;
    }
}
$records=array_values($recordsBySubject);
$term=(string)($_GET['term']??array_key_first($terms)??'');if(!isset($terms[$term]))$term=(string)(array_key_first($terms)??'');
$total=0;$units=0;$selected=null;$termRecords=array_values(array_filter($records,fn($record)=>$record['term']===$term));
foreach($termRecords as $record){$r=$record['release']['snapshot']['students'][$record['live']['enrollment_id']]??null;if($r){$total+=$r['course']*(int)$record['class']['units'];$units+=(int)$record['class']['units'];}if((int)$record['live']['id']===$reqSubject&&$r)$selected=$record;}
portalStart('My grades',$u,'grades');portalHeading('My academic record','View your enrolled subjects and administrator-released grades.');
?><nav class="tabs academic-terms" aria-label="Academic terms"><?php foreach($terms as $key=>$label):?><a class="<?=$key===$term?'active':''?>" href="?<?=h(http_build_query(['term'=>$key]))?>" <?=$key===$term?'aria-current="page"':''?>><?=h($label)?></a><?php endforeach;?></nav>
<div class="metrics academic-summary"><div><small>Enrolled subjects</small><strong><?=count($termRecords)?></strong></div><div><small>Released units</small><strong><?=$units?></strong></div><div><small>Term weighted average</small><strong><?=portalGrade($units?round($total/$units,2):null)?></strong></div></div>
<section class="card"><div class="masterlist-top"><div><h2>My subjects</h2><p class="muted">Only released results appear. Pending classes are excluded from your term average.</p></div><button type="button" class="quiet" onclick="window.print()"><?=portalIcon('file-text')?>Print my term results</button></div><div class="table-wrap" tabindex="0" role="region" aria-label="Released subject grades"><table><thead><tr><th>Subject / section</th><th>Units</th><th>Midterm</th><th>Final</th><th>Course</th><th>Status</th><th>Action</th></tr></thead><tbody>
<?php foreach($termRecords as $record):$s=$record['class'];$live=$record['live'];$release=$record['release'];$r=$release['snapshot']['students'][$live['enrollment_id']]??null;$tone=$r?($r['remarks']==='Passed'?'status-scored':($r['remarks']==='Failed'?'status-missing':'status-excused')):'status-not_graded';?><tr><td><strong><?=h($s['subject_code'].' · '.$s['subject_title'])?></strong><small class="cell-subtitle"><?=h($s['section'])?></small></td><td><?=h($s['units'])?></td><td><?=$r?portalPeriod($r,'midterm',$release['snapshot']['policy']??[]):'—'?></td><td><?=$r?portalPeriod($r,'final',$release['snapshot']['policy']??[]):'—'?></td><td><strong><?=$r?portalGrade($r['course']):'—'?></strong><?php if($r&&!empty($r['converted'])):?><small class="cell-subtitle">Converted: <?=h($r['converted'])?></small><?php endif;?></td><td><span class="score-status-badge <?=$tone?>"><?=$r?h($r['remarks']):'Awaiting released grade'?></span></td><td><?php if($r):?><a class="account-settings-action" href="?<?=h(http_build_query(['term'=>$term,'subject_id'=>$live['id']]))?>#released-subject" aria-label="<?=h('View released grades for '.$s['subject_code'])?>" title="View released grades"><?=portalIcon('file-check-2')?></a><?php else:?>—<?php endif;?></td></tr><?php endforeach;if(!$termRecords):?><tr><td colspan="7">Your verified account has no enrolled classes yet. Contact your professor or the Registrar.</td></tr><?php endif;?></tbody></table></div></section>
<?php if($selected):$release=$selected['release'];$s=$selected['class'];$r=$release['snapshot']['students'][$selected['live']['enrollment_id']];$evidence=cbReviewEvidence($r);$index=max(0,min(count($evidence)-1,(int)($_GET['criterion']??0)));$chosen=$evidence[$index]??null;?>
<section class="card" id="released-subject"><div class="faculty-class-context" style="margin-bottom:18px;background:#f8fafc"><div><span class="eyebrow">RELEASED SUBJECT RECORD</span><h2><?=h($s['subject_code'].' · '.$s['subject_title'])?></h2><p>Released <?=h($release['record']['created_at'])?> · Revision <?=h($release['record']['revision'])?> · Policy: <?=h($release['snapshot']['policy']['policy_label']??'Original default policy')?></p></div><div class="actions"><span class="score-status-badge <?=$r['remarks']==='Passed'?'status-scored':'status-missing'?>"><?=h($r['remarks'])?><?php if(!empty($r['converted'])):?> · <?=h($r['converted'])?><?php endif;?></span><a class="button secondary" href="report.php?subject_id=<?=$selected['live']['id']?>&amp;version=published&amp;release_id=<?=$release['record']['id']?>"><?=portalIcon('download')?>My released report / CSV</a></div></div>
<nav class="tabs" aria-label="Released score categories"><?php foreach($evidence as $i=>$item):?><a class="<?=$i===$index?'active':''?>" href="?<?=h(http_build_query(['term'=>$term,'subject_id'=>$selected['live']['id'],'criterion'=>$i]))?>#released-subject" <?=$i===$index?'aria-current="page"':''?>><?=h(($item['group_label']??CB_GROUPS[$item['group']]).' · '.$item['criterion'])?></a><?php endforeach;?></nav>
<?php if($chosen):?><div class="masterlist-top" style="margin-bottom:12px"><h3><?=h($chosen['criterion'])?> · <?=portalGrade($chosen['percentage'])?></h3><span class="score-status-badge status-not_graded">Weight: <?=h($chosen['weight']??0)?>%</span></div><div class="table-wrap" tabindex="0" role="region" aria-label="Released score evidence"><table><thead><tr><th>Meeting / activity</th><th>Status</th><th>Points</th></tr></thead><tbody><?php foreach($chosen['rows'] as $work):$rawStatus=(string)($work['attendance_status']??$work['status']??'');$workTone=in_array($rawStatus,['present','scored'],true)?'status-scored':(in_array($rawStatus,['absent','missing'],true)?'status-missing':($rawStatus==='excused'?'status-excused':'status-not_graded'));?><tr><td><strong><?=h($work['title'])?></strong></td><td><span class="score-status-badge <?=$workTone?>"><?=h(ucwords(str_replace('_',' ',$rawStatus)))?></span></td><td><?=h($work['earned']??'Pending')?> / <?=h($work['maximum'])?></td></tr><?php endforeach;if(!$chosen['rows']):?><tr><td colspan="3">No work recorded in this release.</td></tr><?php endif;?></tbody></table></div><?php endif;?></section>
<?php endif;?><p class="muted">The term average uses released raw percentages and released unit values. Conversion labels appear separately. Corrections retain the previous published version until released.</p><?php portalEnd();
